21	  struct gkyl_range conf_ext_range, struct gkyl_range phase_ext_range, const struct gkyl_array *phi, 
22	  const struct gkyl_array *fin, struct gkyl_array* flux_surf, struct gkyl_array *cflrate)
23	{ 
24	  int pdim = up->pdim;
25	  int cdim = up->cdim;
26	  int idx[GKYL_MAX_DIM], idx_edge[GKYL_MAX_DIM], idx_vel[2];
27	  int idxL[GKYL_MAX_DIM];
28	  double xc[GKYL_MAX_DIM];
29	
30	  // 2D thread grid
31	  for (unsigned long linc1 = threadIdx.x + blockIdx.x*blockDim.x;
32	      linc1 < phase_range.volume;
33	      linc1 += gridDim.x*blockDim.x)
34	  {
35	    // inverse index from linc1 to idx
36	    // must use gkyl_sub_range_inv_idx so that linc1=0 maps to idx={1,1,...}
37	    // since update_range is a subrange
38	    gkyl_sub_range_inv_idx(&phase_range, linc1, idx);
39	    gkyl_rect_grid_cell_center(&up->phase_grid, idx, xc);
40	
41	    for (int d=cdim; d<pdim; d++) idx_vel[d-cdim] = idx[d];
42	
43	    // convert back to a linear index on the super-range (with ghost cells)
44	    // linc will have jumps in it to jump over ghost cells
45	    long loc_conf = gkyl_range_idx(&conf_range, idx);
