52	    const double *vmapSq_d = (const double*) gkyl_array_cfetch(up->vel_map->vmap_sq, loc_vel);
53	
54	    double* flux_surf_d = (double*) gkyl_array_fetch(flux_surf, loc_phase);
55	    double *cflrate_d = (double*) gkyl_array_fetch(cflrate, loc_phase);
56	
57	    for (int dir = 0; dir<cdim; ++dir) {
58	      gkyl_copy_int_arr(pdim, idx, idxL);
59	      idxL[dir] = idx[dir] - 1;
60	      long loc_confL = gkyl_range_idx(&conf_range, idxL);
61	      long locL = gkyl_range_idx(&phase_range, idxL);
62	      const double *fL = (const double*) gkyl_array_cfetch(fin, locL);
