88	        idx_edge[dir] = idx_edge[dir]+1;
89	        long loc_conf_ext = gkyl_range_idx(&conf_ext_range, idx_edge);
90	        long loc_phase_ext = gkyl_range_idx(&phase_ext_range, idx_edge);
91	
92	        double *cflrate_ext_d = (double*) gkyl_array_fetch(cflrate, loc_phase_ext);
93	        const double *fL = (const double*)  gkyl_array_cfetch(fin, loc_phase);
94	        const double *fR = (const double*)  gkyl_array_cfetch(fin, loc_phase_ext);
95	        const struct gkyl_dg_surf_geom *dgs = gkyl_dg_geom_get_surf(up->dg_geom, dir, idx_edge);
96	        const struct gkyl_gk_dg_surf_geom *gkdgs = gkyl_gk_dg_geom_get_surf(up->gk_dg_geom, dir, idx_edge);
97	
98	        const double *jacgeo_rat_surfL_d = (const double *) gkyl_array_cfetch(up->gk_geom->geo_surf[dir].jacobgeo_ratio, loc_conf);
99	        const double *jacgeo_rat_surfR_d = (const double *) gkyl_array_cfetch(up->gk_geom->geo_surf[dir].jacobgeo_ratio, loc_conf_ext);
100	
101	        double* flux_surf_ext_d = (double*) gkyl_array_fetch(flux_surf, loc_phase_ext);
102	
103	        cflrate_ext_d[0] = up->flux_surf_edge_up[dir](xc, up->phase_grid.dx, vmap_d, vmapSq_d, up->charge, up->mass,
104	          dgs, gkdgs, bmag_d, jacgeo_rat_surfL_d, jacgeo_rat_surfR_d, phi_d, fL, fR, flux_surf_ext_d);
105	      }  
106	    }
