29	  for (unsigned long linc1 = threadIdx.x + blockIdx.x*blockDim.x;
30	      linc1 < phase_range.volume;
31	      linc1 += gridDim.x*blockDim.x)
32	  {
33	    gkyl_sub_range_inv_idx(&phase_range, linc1, idx);
34	    gkyl_rect_grid_cell_center(&up->phase_grid, idx, xc);
35	
36	    for (int d = cdim; d < pdim; d++) idx_vel[d-cdim] = idx[d];
