61	      const double *jacgeo_rat_surfR_d = (const double*) gkyl_array_cfetch(up->gk_geom->geo_surf[dir].jacobgeo_ratio, loc_conf);
62	
63	      const double *speeds_L = (const double*) gkyl_array_cfetch(up->passive_speeds, loc_confL);
64	      const double *speeds_R = (const double*) gkyl_array_cfetch(up->passive_speeds, loc_conf);
65	
66	      if (idx[dir] == phase_range.lower[dir]) {
67	        // Lower domain/block boundary.
68	        cflrate_d[0] += up->flux_surf_edge_lo[dir](xc, up->phase_grid.dx,
69	          vmap_d, vmapSq_d, up->charge, up->mass,
