141	gkyl_gk_collisionless_passive_flux*
142	gkyl_gk_collisionless_passive_flux_cu_dev_new(const struct gkyl_rect_grid *phase_grid,
143	  const struct gkyl_basis *conf_basis, const struct gkyl_basis *phase_basis,
144	  const struct gkyl_array *passive_speeds,
145	  const double charge, const double mass,
146	  const struct gk_geometry *gk_geom, const struct gkyl_dg_geom *dg_geom,
147	  const struct gkyl_gk_dg_geom *gk_dg_geom, const struct gkyl_velocity_map *vel_map,
148	  const enum gkyl_gyrokinetic_bc_type *bctype_conf)
149	{
150	  gkyl_gk_collisionless_passive_flux *up =
151	    (gkyl_gk_collisionless_passive_flux*) gkyl_malloc(sizeof(*up));
152	
153	  up->phase_grid = *phase_grid;
154	  int cdim = conf_basis->ndim;
155	  int pdim = phase_basis->ndim;
156	  int vdim = pdim - cdim;
157	  int poly_order = phase_basis->poly_order;
158	  up->cdim = cdim;
159	  up->pdim = pdim;
160	
161	  up->charge = charge;
162	  up->mass   = mass;
163	
164	  // Store on_dev pointers so the memcpy below carries device-side array references.
165	  up->passive_speeds = passive_speeds->on_dev;
166	
167	  // Acquire geometry/vel_map and use their on_dev pointers for the device copy.
168	  struct gk_geometry       *geom_ho        = gkyl_gk_geometry_acquire(gk_geom);
169	  struct gkyl_dg_geom      *dg_geom_ho     = gkyl_dg_geom_acquire(dg_geom);
170	  struct gkyl_gk_dg_geom   *gk_dg_geom_ho  = gkyl_gk_dg_geom_acquire(gk_dg_geom);
171	  struct gkyl_velocity_map *vel_map_ho     = gkyl_velocity_map_acquire(vel_map);
172	
173	  up->gk_geom    = geom_ho->on_dev;
174	  up->dg_geom    = dg_geom_ho->on_dev;
175	  up->gk_dg_geom = gk_dg_geom_ho->on_dev;
176	  up->vel_map    = vel_map_ho->on_dev;
177	
178	  up->flags = 0;
179	  GKYL_SET_CU_ALLOC(up->flags);
180	
181	  // Temporarily copy array of BCs to device for kernel selection.
182	  enum gkyl_gyrokinetic_bc_type *bctype_conf_dev = (enum gkyl_gyrokinetic_bc_type *) gkyl_cu_malloc(2*GKYL_MAX_CDIM*sizeof(enum gkyl_gyrokinetic_bc_type));
183	  gkyl_cu_memcpy(bctype_conf_dev, bctype_conf, 2*GKYL_MAX_CDIM*sizeof(enum gkyl_gyrokinetic_bc_type), GKYL_CU_MEMCPY_H2D);
184	
185	  // Copy host struct to device and select kernels.
186	  struct gkyl_gk_collisionless_passive_flux *up_cu =
187	    (struct gkyl_gk_collisionless_passive_flux*) gkyl_cu_malloc(sizeof(*up_cu));
188	  gkyl_cu_memcpy(up_cu, up, sizeof(*up), GKYL_CU_MEMCPY_H2D);
189	
190	  gk_collisionless_passive_flux_set_cu_dev_ptrs<<<1,1>>>(up_cu, cdim, vdim, poly_order, bctype_conf_dev);
191	
192	  gkyl_cu_free(bctype_conf_dev);
193	
194	  up->on_dev = up_cu;
195	
196	  // Restore host-side pointers for the host updater.
197	  up->passive_speeds = passive_speeds;
198	
199	  up->gk_geom    = geom_ho;
200	  up->dg_geom    = dg_geom_ho;
201	  up->gk_dg_geom = gk_dg_geom_ho;
202	  up->vel_map    = vel_map_ho;
203	
204	  return up;
205	}
